    const BOOT_KEY = 'jianlai-qingming-boot-v1';

    function bootAllowed() {
      try {
        if (typeof window === 'undefined') return false;
        const value = new URLSearchParams(window.location.search).get('boot');
        if (value === '0') return false;
        if (value === '1') return true;
        return window.sessionStorage.getItem(BOOT_KEY) !== '1';
      } catch (error) {
        return true;
      }
    }

    function JianBoot() {
      const [visible, setVisible] = React.useState(bootAllowed);
      const [leaving, setLeaving] = React.useState(false);

      React.useEffect(() => {
        if (!visible) return undefined;

        try {
          window.sessionStorage.setItem(BOOT_KEY, '1');
        } catch (error) {
          /* the veil can replay when storage is unavailable */
        }

        let alive = true;
        let hideTimer;
        const reduced =
          typeof window.matchMedia === 'function' &&
          window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        const hold = reduced ? 480 : 1800;

        const dismiss = () => {
          if (!alive) return;
          alive = false;
          setLeaving(true);
          hideTimer = window.setTimeout(() => setVisible(false), 280);
        };

        const leaveTimer = window.setTimeout(dismiss, hold);
        const onKey = (event) => {
          if (event && typeof event.preventDefault === 'function') {
            event.preventDefault();
          }
          if (event && typeof event.stopPropagation === 'function') {
            event.stopPropagation();
          }
          dismiss();
        };
        const onPointer = (event) => {
          if (event && typeof event.preventDefault === 'function') {
            event.preventDefault();
          }
          dismiss();
        };
        window.addEventListener('keydown', onKey, { once: true, capture: true });
        window.addEventListener('pointerdown', onPointer, {
          once: true,
          capture: true,
        });

        return () => {
          alive = false;
          window.clearTimeout(leaveTimer);
          window.clearTimeout(hideTimer);
          window.removeEventListener('keydown', onKey, true);
          window.removeEventListener('pointerdown', onPointer, true);
        };
      }, [visible]);

      if (!visible) return null;

      return h(
        'div',
        {
          className: 'jian-boot' + (leaving ? ' jian-boot--leaving' : ''),
          role: 'presentation',
          'aria-hidden': 'true',
        },
        h('span', { className: 'jian-boot__art' }),
        h('span', { className: 'jian-boot__moon' }),
        h('span', { className: 'jian-boot__line' }),
        h(
          'div',
          { className: 'jian-boot__content' },
          h('span', { className: 'jian-boot__kicker' }, 'MMXXVI · 剑起青冥'),
          h('span', { className: 'jian-boot__title' }, '剑冢'),
          h('span', { className: 'jian-boot__latin' }, 'QINGMING · SWORD COMES'),
          h(
            'span',
            { className: 'jian-boot__rule' },
            h('span', { className: 'jian-boot__gem' })
          ),
          h(
            'span',
            { className: 'jian-boot__verse' },
            '我有一剑，可搬山、倒海、降妖、镇魔……'
          ),
          h('span', { className: 'jian-boot__progress' }, h('span')),
          h(
            'span',
            { className: 'jian-boot__hint' },
            'CLICK OR PRESS ANY KEY TO ENTER',
            h('span', { className: 'jian-boot__replay' }, '  ·  ?boot=1 REPLAY')
          )
        )
      );
    }


    const WHALE_HUD_PARTS = [
      ['jianw-hud__line', ''],
      ['jianw-hud__seal', '剑'],
      ['jianw-hud__spine', '剑葫'],
      ['jianw-hud__sub', 'QINGMING'],
      ['jianw-hud__rail', '一剑'],
    ];

    function installWhaleSkin(ctx) {
      ctx.effect(() => {
        if (typeof window === 'undefined' || typeof document === 'undefined') {
          return undefined;
        }

        const html = document.documentElement;
        html.classList.add('qingming-whale');

        let disposed = false;
        let imgObserver = null;
        let bodyObserver = null;
        let currentImg = null;
        let lastRoleSrc = null;
        let hud = null;

        const findRoot = () => document.querySelector('.dshwv-root');
        const findImg = (root) => (root ? root.querySelector('.dshwv-img') : null);

        const ensureHud = (root) => {
          if (!root) return;
          const host = root.querySelector('.dshwv-body') || root;
          if (hud && hud.isConnected && hud.parentElement === host) return;
          hud = null;
          const existing = host.querySelector('.jianw-hud');
          if (existing) {
            hud = existing;
            return;
          }
          hud = document.createElement('div');
          hud.className = 'jianw-hud';
          hud.setAttribute('aria-hidden', 'true');
          for (const [className, text] of WHALE_HUD_PARTS) {
            const node = document.createElement('span');
            node.className = className;
            node.setAttribute('aria-hidden', 'true');
            if (text) node.textContent = text;
            hud.appendChild(node);
          }
          host.insertBefore(hud, host.firstChild || null);
        };

        const ensureArt = (img) => {
          if (!img) return;
          const src = img.getAttribute('src') || '';
          if (src && src !== WHALE_GOURD) {
            lastRoleSrc = src;
          }
          if (!img.dataset.jianlaiWhaleOriginalSrc) {
            img.dataset.jianlaiWhaleOriginalSrc = src;
            img.dataset.jianlaiWhaleOriginalClip = img.style.clipPath || '';
            img.dataset.jianlaiWhaleOriginalWebkitClip = img.style.webkitClipPath || '';
          }
          if (src !== WHALE_GOURD) {
            img.setAttribute('src', WHALE_GOURD);
          }
          img.style.setProperty('clip-path', 'none', 'important');
          img.style.setProperty('-webkit-clip-path', 'none', 'important');
          if (img !== currentImg) {
            currentImg = img;
            if (imgObserver) imgObserver.disconnect();
            if (typeof MutationObserver === 'function') {
              imgObserver = new MutationObserver(() => ensureArt(img));
              imgObserver.observe(img, { attributes: true, attributeFilter: ['src'] });
            }
          }
        };

        const restoreArt = (img) => {
          if (!img) return;
          const src = lastRoleSrc || img.dataset.jianlaiWhaleOriginalSrc;
          const clip = img.dataset.jianlaiWhaleOriginalClip || '';
          const webkit = img.dataset.jianlaiWhaleOriginalWebkitClip || '';
          if (src) img.setAttribute('src', src);
          try {
            if (clip) img.style.setProperty('clip-path', clip);
            else img.style.removeProperty('clip-path');
            if (webkit) img.style.setProperty('-webkit-clip-path', webkit);
            else img.style.removeProperty('-webkit-clip-path');
          } catch (error) {
            /* the widget owns these inline styles; best effort restore */
          }
          delete img.dataset.jianlaiWhaleOriginalSrc;
          delete img.dataset.jianlaiWhaleOriginalClip;
          delete img.dataset.jianlaiWhaleOriginalWebkitClip;
        };

        const apply = () => {
          if (disposed) return;
          const root = findRoot();
          if (!root) return;
          // The gourd is the important half of the skin; a HUD failure must
          // not prevent the character swap, the theme slots, or later retries.
          try {
            ensureArt(findImg(root));
          } catch (error) {
            /* the widget may be between mounts; retry on the next tick */
          }
          try {
            ensureHud(root);
          } catch (error) {
            /* a HUD failure is cosmetic; never break the theme */
          }
        };

        apply();
        const timers = [80, 240, 600, 1200, 2400, 4000].map((delay) =>
          window.setTimeout(apply, delay),
        );
        const interval = window.setInterval(apply, 1600);

        if (typeof MutationObserver === 'function') {
          bodyObserver = new MutationObserver(apply);
          try {
            bodyObserver.observe(document.body, { childList: true });
          } catch (error) {
            bodyObserver = null;
          }
        }

        try {
          window.__jianlaiWhaleSkin = { art: WHALE_GOURD, refresh: apply };
        } catch (error) {
          /* debugging hook is optional */
        }

        return () => {
          disposed = true;
          timers.forEach((id) => window.clearTimeout(id));
          window.clearInterval(interval);
          if (imgObserver) imgObserver.disconnect();
          if (bodyObserver) bodyObserver.disconnect();

          for (const node of document.querySelectorAll('.jianw-hud')) {
            node.remove();
          }
          const root = findRoot();
          restoreArt(findImg(root) || findImg(document.body));
          html.classList.remove('qingming-whale');
          hud = null;
          currentImg = null;
          lastRoleSrc = null;

          try {
            delete window.__jianlaiWhaleSkin;
          } catch (error) {
            /* ignore */
          }
        };
      }, 'jianlai-qingming: whale widget skin');
    }
